import numpy as np
# 2 个潜在策略，3 种动作；按策略采样序列
def sample_seq(T, P_strategy, P_act):
    s = 0; seq = []
    for _ in range(T):
        s = np.random.choice(len(P_strategy), p=P_strategy[s])
        seq.append(np.random.choice(len(P_act[s]), p=P_act[s]))
    return np.array(seq)
seq = sample_seq(20, np.array([[.9,.1],[.2,.8]]), np.array([[.6,.3,.1],[.1,.3,.6]]))
print(seq[:10])

import torch
F, R = {3, 7}, {1, 2, 4, 5, 6}   # 全注意力层与循环层下标
def layer(h, l, full_fn, rec_fn):
    return full_fn(h) if l in F else rec_fn(h)
h = torch.randn(2, 8, 64)
for l in range(1, 8):
    h = layer(h, l, lambda x: x, lambda x: x * 0.99)  # 占位算子
print(h.shape)  # torch.Size([2, 8, 64])
